}

void velocityVerletStep1(vec3& pos, vec3& vel, const vec3& force, double mass, double dt) {
    // Update velocity by half timestep
    double invMass = 1.0 / mass;
    double halfDt = dt / 2.0;
    vec3 acceleration;
    acceleration.x = force.x * invMass;
    acceleration.y = force.y * invMass;
    acceleration.z = force.z * invMass;

    vel.x += acceleration.x * halfDt;
    vel.y += acceleration.y * halfDt;
    vel.z += acceleration.z * halfDt;

    // Update position by full timestep
    pos.x += vel.x * dt;
    pos.y += vel.y * dt;
    pos.z += vel.z * dt;
}

void velocityVerletStep1(vec3& pos, vec3& vel, const vec3& force, double mass, double dt) {
    // Update velocity by half timestep
    vec3 acceleration = force * (1.0 / mass);
    vec3 velHalfStep = vel + acceleration * (dt / 2.0);
    vel = velHalfStep;

    // Update position by full timestep
    vec3 posFullStep = pos + vel * dt;
    pos = posFullStep;
}

